CREATE TABLE public.empresas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), nome text NOT NULL, categoria text NOT NULL DEFAULT '', cidade text NOT NULL DEFAULT '', bairro text NOT NULL DEFAULT '', telefone text NOT NULL, site text DEFAULT '', instagram text DEFAULT '', nota_google numeric DEFAULT 0, avaliacoes_google integer DEFAULT 0, observacao text DEFAULT '', origem text DEFAULT 'manual', saiu boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,telefone));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.empresas TO authenticated; GRANT ALL ON public.empresas TO service_role;
ALTER TABLE public.empresas ENABLE ROW LEVEL SECURITY;
CREATE POLICY own ON public.empresas FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.contatos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), empresa_id uuid NOT NULL REFERENCES public.empresas(id) ON DELETE CASCADE UNIQUE, status text NOT NULL DEFAULT 'a_mandar' CHECK(status IN ('a_mandar','enviado','respondeu','reuniao','fechou','sem_interesse')), sistema_sugerido text DEFAULT '', mensagem text DEFAULT '', follow_up text DEFAULT '', enviado_em timestamptz, follow_up_em date, respondeu_em timestamptz, anotacao text DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.contatos TO authenticated; GRANT ALL ON public.contatos TO service_role;
ALTER TABLE public.contatos ENABLE ROW LEVEL SECURITY;
CREATE POLICY own ON public.contatos FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.empresas e WHERE e.id=empresa_id AND e.user_id=auth.uid()));
CREATE TABLE public.ofertas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), nome text NOT NULL, para_quem text NOT NULL DEFAULT '', dor text NOT NULL DEFAULT '', resultado text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.ofertas TO authenticated; GRANT ALL ON public.ofertas TO service_role;
ALTER TABLE public.ofertas ENABLE ROW LEVEL SECURITY;
CREATE POLICY own ON public.ofertas FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.configuracoes (user_id uuid NOT NULL DEFAULT auth.uid(), chave text NOT NULL, valor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,chave));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.configuracoes TO authenticated; GRANT ALL ON public.configuracoes TO service_role;
ALTER TABLE public.configuracoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY own ON public.configuracoes FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), tipo text NOT NULL, detalhe jsonb NOT NULL DEFAULT '{}', criado_em timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.logs TO authenticated; GRANT ALL ON public.logs TO service_role;
ALTER TABLE public.logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own ON public.logs FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE INDEX empresas_owner ON public.empresas(user_id); CREATE INDEX contatos_owner ON public.contatos(user_id); CREATE INDEX ofertas_owner ON public.ofertas(user_id); CREATE INDEX logs_owner ON public.logs(user_id);
CREATE FUNCTION public.registrar_envio(p_contato uuid, p_mensagem text, p_follow boolean DEFAULT false) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.contatos; e public.empresas; lim int; total int; hoje date := (now() AT TIME ZONE 'America/Sao_Paulo')::date; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Login necessário'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0)); SELECT * INTO c FROM public.contatos WHERE id=p_contato AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Contato não encontrado'; END IF; SELECT * INTO e FROM public.empresas WHERE id=c.empresa_id AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND OR e.saiu THEN RAISE EXCEPTION 'Empresa bloqueada'; END IF; IF length(trim(p_mensagem))=0 THEN RAISE EXCEPTION 'Mensagem vazia'; END IF; IF p_follow THEN IF c.status<>'enviado' OR c.follow_up_em IS NULL OR c.follow_up_em>hoje THEN RAISE EXCEPTION 'Follow-up indisponível'; END IF; UPDATE public.contatos SET follow_up_em=NULL WHERE id=c.id; ELSE IF c.status<>'a_mandar' THEN RAISE EXCEPTION 'Primeira mensagem já registrada'; END IF; SELECT COALESCE((SELECT valor::int FROM public.configuracoes WHERE user_id=auth.uid() AND chave='limite'),20) INTO lim; SELECT count(*) INTO total FROM public.logs WHERE user_id=auth.uid() AND tipo='envio' AND (created_at AT TIME ZONE 'America/Sao_Paulo')::date=hoje; IF total>=lim THEN RAISE EXCEPTION 'Limite diário atingido'; END IF; IF position('se não fizer sentido' in lower(p_mensagem))=0 THEN RAISE EXCEPTION 'Inclua a instrução de saída'; END IF; UPDATE public.contatos SET status='enviado',mensagem=p_mensagem,enviado_em=now(),follow_up_em=hoje+3 WHERE id=c.id; END IF; INSERT INTO public.logs(user_id,tipo,detalhe) VALUES(auth.uid(),CASE WHEN p_follow THEN 'follow_up' ELSE 'envio' END,jsonb_build_object('contato_id',c.id,'mensagem',p_mensagem,'confirmacao','abertura_whatsapp')); RETURN e.telefone; END; $$;
REVOKE ALL ON FUNCTION public.registrar_envio(uuid,text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.registrar_envio(uuid,text,boolean) TO authenticated;
CREATE FUNCTION public.salvar_geracao(p_contato uuid,p_mensagem text,p_follow text,p_oferta text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.contatos SET mensagem=p_mensagem,follow_up=p_follow,sistema_sugerido=p_oferta WHERE id=p_contato AND user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Contato não encontrado'; END IF; INSERT INTO public.logs(user_id,tipo,detalhe) VALUES(auth.uid(),'geracao',jsonb_build_object('contato_id',p_contato,'mensagem',p_mensagem,'oferta',p_oferta)); END; $$;
REVOKE ALL ON FUNCTION public.salvar_geracao(uuid,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.salvar_geracao(uuid,text,text,text) TO authenticated;
CREATE FUNCTION public.criar_contato() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.contatos(user_id,empresa_id) VALUES(NEW.user_id,NEW.id); RETURN NEW; END; $$;
CREATE TRIGGER empresa_contato AFTER INSERT ON public.empresas FOR EACH ROW EXECUTE FUNCTION public.criar_contato();